insert into public.reflection_translations (id, reflection_id, language, title, content) values ($c$tr-4$c$, $c$1$c$, $c$fr$c$, $c$Pas parce que j’avais besoin de toi$c$, $c$Hi ha moments a la vida en què no tens ni idea que estàs a punt de començar una etapa nova. No hi ha música de fons, ni una llum especial, ni una veu que et digui que el que està passant ara et canviarà la vida. Simplement estàs fent la teva vida i, de sobte, algú et diu una frase que no esperaves escoltar i et quedes intentant entendre en quin moment has passat de tenir-ho tot més o menys controlat a no saber ni què faràs l'endemà.

